  9	import { ACPClient, type ACPClientOptions } from "../acp/index.js";
 10	import type { AgentAdapter } from "./adapters.js";
 11	
 12	/**
 13	 * Options for spawning an agent.
 14	 */
 15	export interface SpawnAgentOptions {
 16	  /** Working directory for the agent */
 17	  cwd: string;
 18	  /** Additional environment variables */
 19	  env?: Record<string, string>;
 20	  /** Extra arguments to append (e.g., auto-approve flags) */
 21	  extraArgs?: string[];
 22	  /** ACP client options */
 23	  clientOptions?: Omit<ACPClientOptions, "stdin" | "stdout">;
 24	}
 25	
 26	/**
 27	 * Result of spawning an agent.
 28	 */
 29	export interface SpawnedAgent {
 30	  /** The ACP client for communication */
 31	  client: ACPClient;
 32	  /** The child process handle */
 33	  process: ChildProcess;
 34	  /** Kill the agent process */
 35	  kill: (signal?: NodeJS.Signals) => void;
 36	}
 37	
 38	/**
 39	 * Environment variables to strip from the parent process before spawning agents.
 40	 * These vars cause agent runtimes to detect a "nested session" and refuse to start
 41	 * when the daemon itself was launched from within such an environment.
 42	 */
 43	export const SANITIZED_ENV_VARS = ["CLAUDECODE", "CLAUDE_CODE_SESSION"] as const;
 44	
 45	const UNEXPECTED_CASE_PREFIX = "Unexpected case:";
 46	const RATE_LIMIT_EVENT_TYPE = "rate_limit_event";
 47	
 48	function isNonActionableAdapterStderrLine(line: string): boolean {
 49	  const trimmed = line.trim();
 50	  if (!trimmed.startsWith(UNEXPECTED_CASE_PREFIX)) return false;
 51	
 52	  const payload = trimmed.slice(UNEXPECTED_CASE_PREFIX.length).trim();
 53	  if (!payload) return false;
 54	
 55	  try {
 56	    const parsed = JSON.parse(payload) as { type?: string };
 57	    return parsed.type === RATE_LIMIT_EVENT_TYPE;
 58	  } catch {
 59	    // Keep a narrow fallback pattern in case adapter logs malformed JSON.
 60	    return /"type"\s*:\s*"rate_limit_event"/.test(payload);
 61	  }
 62	}
 63	
 64	function forwardFilteredAdapterStderr(child: ChildProcess): void {
 65	  if (!child.stderr) return;
 66	
 67	  child.stderr.setEncoding("utf-8");
 68	  let pending = "";
 69	
 70	  const forward = (line: string, withNewline: boolean): void => {
 71	    if (isNonActionableAdapterStderrLine(line)) return;
 72	    process.stderr.write(withNewline ? `${line}\n` : line);
 73	  };
 74	
 75	  child.stderr.on("data", (chunk: string | Buffer) => {
 76	    pending += chunk.toString();
 77	    let newlineIndex = pending.indexOf("\n");
 78	
 79	    while (newlineIndex !== -1) {
 80	      const line = pending.slice(0, newlineIndex);
 81	      pending = pending.slice(newlineIndex + 1);
 82	      forward(line, true);
 83	      newlineIndex = pending.indexOf("\n");
 84	    }
 85	  });
 86	
 87	  child.stderr.on("end", () => {
 88	    if (pending.length > 0) {
 89	      forward(pending, false);
 90	    }
 91	  });
 92	}
 93	
 94	/**
 95	 * Spawn an ACP agent using the specified adapter.
 96	 *
 97	 * Creates a child process and wraps its stdio with an ACPClient.
 98	 * The caller is responsible for calling client.initialize() after spawning.
 99	 *
100	 * @param adapter - Adapter definition specifying how to spawn the agent
101	 * @param options - Spawn options including cwd and environment
102	 * @returns SpawnedAgent with client, process, and kill function
103	 */
104	export function spawnAgent(
105	  adapter: AgentAdapter,
106	  options: SpawnAgentOptions,
107	): SpawnedAgent {
108	  const { cwd, env = {}, extraArgs, clientOptions = {} } = options;
109	
110	  // Strip host-environment variables that interfere with agent startup
111	  // (e.g. CLAUDECODE=1 causes nested-session detection in Claude Code)
112	  const cleanProcessEnv = { ...process.env };
113	  for (const key of SANITIZED_ENV_VARS) {
114	    delete cleanProcessEnv[key];
115	  }
116	
117	  // Merge environment variables
118	  const processEnv = {
119	    ...cleanProcessEnv,
120	    ...adapter.env,
121	    ...env,
122	  };
123	
124	  // Build args from fresh copy to prevent cross-call leakage
125	  const args = [...adapter.args, ...(extraArgs || [])];
126	
127	  // Spawn the agent process
128	  const child = spawn(adapter.command, args, {
129	    cwd,
130	    env: processEnv,
131	    shell: adapter.shell,
132	    stdio: ["pipe", "pipe", "pipe"], // pipe all stdio so stderr can be filtered
133	  });
134	
135	  // Keep actionable adapter stderr visible while dropping known non-actionable noise.
136	  forwardFilteredAdapterStderr(child);
137	
138	  // Ensure stdin/stdout are available
139	  if (!child.stdin || !child.stdout) {
140	    child.kill();
141	    throw new Error("Failed to create pipes for agent process");
142	  }
143	
144	  // Create ACP client connected to child's stdio
145	  // Note: From the client's perspective:
146	  // - stdin is where we READ from (child's stdout)
147	  // - stdout is where we WRITE to (child's stdin)
148	  const client = new ACPClient({
149	    ...clientOptions,
150	    stdin: child.stdout, // We read from child's stdout
151	    stdout: child.stdin as NodeJS.WritableStream, // We write to child's stdin
152	  });
153	
154	  // Forward process exit to client close, surfacing exit code/signal
155	  child.on("exit", (code, signal) => {
156	    if (!client.isClosed()) {
157	      let reason: string;
158	      if (signal !== null) {
159	        reason = `Subagent process exited with signal ${signal}`;
160	      } else if (code !== null) {
161	        reason = `Subagent process exited with code ${code}`;
162	      } else {
163	        reason = "Subagent process exited unexpectedly";
164	      }
165	      client.close(reason);
166	    }
167	  });
168	
169	  // Kill function with graceful shutdown
170	  const kill = (signal: NodeJS.Signals = "SIGTERM"): void => {
171	    if (!child.killed) {
172	      child.kill(signal);
173	    }
174	  };
175	
176	  return { client, process: child, kill };
177	}
178	
179	/**
180	 * Spawn and initialize an ACP agent.
181	 *
182	 * Convenience function that spawns an agent and calls initialize().
183	 *
184	 * @param adapter - Adapter definition
185	 * @param options - Spawn options
186	 * @returns Initialized SpawnedAgent
187	 */
188	export async function spawnAndInitialize(
189	  adapter: AgentAdapter,
190	  options: SpawnAgentOptions,
191	): Promise<SpawnedAgent> {
192	  const agent = spawnAgent(adapter, options);
193	
194	  try {
195	    await agent.client.initialize();
196	    return agent;
197	  } catch (err) {
198	    // Clean up on initialization failure
199	    agent.kill();
200	    throw err;
201	  }
202	}

