 32	
 33	let sessionId = null;
 34	let initialized = false;
 35	/** Map of pending outgoing requests: id → { resolve, reject } */
 36	const pendingRequests = new Map();
 37	
 38	// ─── Environment Config ──────────────────────────────────────────────────────
 39	
 40	const exitCode = parseInt(process.env.MOCK_ACP_EXIT_CODE || '0', 10);
 41	const failCount = parseInt(process.env.MOCK_ACP_FAIL_COUNT || '0', 10);
 42	const stateFile = process.env.MOCK_ACP_STATE_FILE;
 43	const delayMs = parseInt(process.env.MOCK_ACP_DELAY_MS || '0', 10);
 44	const responseText = process.env.MOCK_ACP_RESPONSE_TEXT || 'Mock response';
 45	const stopReason = process.env.MOCK_ACP_STOP_REASON || 'end_turn';
