 47	const needsWorkTask = process.env.MOCK_ACP_NEEDS_WORK_TASK;
 48	const projectDir = process.env.MOCK_ACP_PROJECT_DIR;
 49	const cliPath = process.env.MOCK_ACP_CLI_PATH || 'kspec';
 50	// Write specified env var values to a file for test verification
 51	const verifyEnvFile = process.env.MOCK_ACP_VERIFY_ENV_FILE;
 52	const verifyEnvVars = process.env.MOCK_ACP_VERIFY_ENV_VARS; // comma-separated var names
