 58	
 59	// ─── JSON-RPC Helpers ────────────────────────────────────────────────────────
 60	
 61	function sendResponse(id, result) {
 62	  const response = { jsonrpc: '2.0', id, result };
 63	  console.log(JSON.stringify(response));
 64	}
 65	
 66	let nextRequestId = 1;
 67	/**
