 69	 * Used for permission requests where the agent asks the client to approve a tool call.
 70	 */
 71	function sendOutgoingRequest(method, params) {
 72	  return new Promise((resolve, reject) => {
 73	    const id = `mock-req-${nextRequestId++}`;
 74	    pendingRequests.set(id, { resolve, reject });
 75	    const request = { jsonrpc: '2.0', id, method, params };
 76	    console.log(JSON.stringify(request));
 77	  });
 78	}
 79	
 80	function sendError(id, code, message) {
 81	  const response = { jsonrpc: '2.0', id, error: { code, message } };
 82	  console.log(JSON.stringify(response));
 83	}
 84	
 85	function sendNotification(method, params) {
 86	  const notification = { jsonrpc: '2.0', method, params };
 87	  console.log(JSON.stringify(notification));
 88	}
 89	
 90	// ─── Failure Tracking ────────────────────────────────────────────────────────
 91	
 92	function shouldFail() {
 93	  if (failCount <= 0 || !stateFile) {
 94	    return exitCode !== 0;
 95	  }
 96	
 97	  // Track call count in state file
 98	  let callCount = 0;
 99	  try {
100	    callCount = parseInt(fs.readFileSync(stateFile, 'utf-8').trim(), 10) || 0;
101	  } catch {
102	    // File doesn't exist yet
103	  }
104	  callCount++;
105	  fs.writeFileSync(stateFile, String(callCount));
106	
107	  // Fail until we've been called failCount times
108	  if (callCount <= failCount) {
109	    console.error(`Mock ACP: Simulated failure ${callCount}/${failCount}`);
110	    return true;
111	  }
112	
113	  console.error(`Mock ACP: Success after ${failCount} failures`);
114	  return false;
115	}
116	
117	// ─── Request Handlers ────────────────────────────────────────────────────────
118	
119	async function handleInitialize(id, _params) {
120	  initialized = true;

